import { defineTool, ToolError } from "@lovable.dev/mcp-js";
import { z } from "zod";
import data from "../data.json";
/* data.json is generated by scripts/mcp-snapshot.ts; it is dynamic JSON by design. */
/* eslint-disable @typescript-eslint/no-explicit-any */
const products = data.products as any[];
const blogPosts = data.blogPosts as any[];
const services = data.services as any[];

const SITE_ORIGIN = "https://woodex.pk";
const STRIP_TAGS = /<[^>]*>/g;

const stripTags = (s: any) => String(s ?? "").replace(STRIP_TAGS, " ").replace(/\s+/g, " ").trim();
const wordCount = (t: string) => (stripTags(t).match(/\S+/g) ?? []).length;
const norm = (t: string) => stripTags(t).toLowerCase();
const includesKey = (haystack: string, needle: string) => norm(haystack).includes(norm(needle).trim());
const countKey = (haystack: string, needle: string) => {
  const hay = norm(haystack); const key = norm(needle).trim();
  if (!key) return 0;
  let count = 0; let idx = hay.indexOf(key);
  while (idx !== -1) { count += 1; idx = hay.indexOf(key, idx + key.length); }
  return count;
};
const kebab = (t: string) => norm(t).replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60).replace(/-+$/g, "");
const trimWords = (t: string, max: number) => {
  const text = stripTags(t);
  if (text.length <= max) return text;
  const cut = text.slice(0, max + 1);
  const last = cut.lastIndexOf(" ");
  return (last > max * 0.5 ? cut.slice(0, last) : cut.slice(0, max)).replace(/[\s\-–—,;:|]+$/g, "") + (text.length > max ? "…" : "");
};

type SeoPage = {
  type: "home" | "product" | "blog" | "service";
  id: string;
  path: string;
  title: string;
  description: string;
  body: string;
  headings: number;
  facts: Record<string, unknown>;
}

const resolvePage = (path: string): SeoPage => {
  const clean = String(path ?? "").trim();
  if (clean === "" || clean[0] !== "/") {
    throw new ToolError("path must start with '/'. Examples: /, /product/ballmer-executive-desk, /blog/<id>, /service/<slug>.");
  }
  if (clean === "/") {
    return {
      type: "home", id: "home", path: "/",
      title: "WOODEX — Furniture that outlasts the brief",
      description: "WOODEX, Lahore's furniture maker since 1986 — office, home and hospitality furniture, engineered in our own workshop with a 5-year warranty and nationwide delivery.",
      body: "WOODEX manufactures office furniture, home furniture and hospitality fitouts in Lahore, Pakistan. Engineered-wood and steel construction, in-house joinery, quality gates, 5-year warranty, nationwide delivery and installation, and after-sales service. Showrooms across Lahore with design consultants and made-to-order options for homes, offices and hotels.",
      headings: 3,
      facts: { warranties: "5-year", founded: 1986 },
    };
  }
  const product = clean.match(/^\/product\/([^/]+)\/?$/);
  if (product) {
    const p = products.find((x) => x.id === product[1]);
    if (!p) throw new ToolError(`No product "${product[1]}" in the snapshot. Example ids: ${products.slice(0, 3).map((x) => x.id).join(", ")}…`);
    return {
      type: "product", id: p.id, path: clean,
      title: String(p.name),
      description: String(p.shortDescription || p.description || ""),
      body: stripTags([p.description, ...(p.features ?? [])].join(". ")),
      headings: 1,
      facts: { pricePkr: p.price, inStock: p.inStock, rating: p.rating, reviews: p.reviews },
    };
  }
  const blog = clean.match(/^\/blog\/([^/]+)\/?$/);
  if (blog) {
    const p = blogPosts.find((x) => x.id === blog[1]);
    if (!p) throw new ToolError(`No blog article "${blog[1]}" in the snapshot. Available ids: ${blogPosts.map((x) => x.id).join(", ")}`);
    const content = p.content ?? [];
    return {
      type: "blog", id: p.id, path: clean,
      title: String(p.title),
      description: String(p.excerpt ?? ""),
      body: stripTags(content.map((c: any) => (c.heading ? `${c.heading}. ` : "") + c.body).join(" ")),
      headings: content.filter((c: any) => c.heading).length,
      facts: { date: p.date, readTime: p.readTime, tags: p.tags },
    };
  }
  const service = clean.match(/^\/service\/([^/]+)\/?$/);
  if (service) {
    const s = services.find((x) => x.slug === service[1]);
    if (!s) throw new ToolError(`No service "${service[1]}" in the snapshot. Available slugs: ${services.map((x) => x.slug).join(", ")}`);
    const benefits = (s.benefits ?? []).map((b: any) => `${b.title} — ${b.description}`).join(". ");
    const faqs = (s.faqs ?? []).map((f: any) => `${f.q} ${f.a}`).join(" ");
    const overview = s.overview && typeof s.overview === "object" ? `${s.overview.heading ?? ""}. ${s.overview.body ?? ""}` : String(s.overview ?? "");
    return {
      type: "service", id: s.slug, path: clean,
      title: String(s.metaTitle || s.title),
      description: String(s.metaDescription || s.tagline || s.intro || ""),
      body: stripTags([overview, s.intro, benefits, (s.inclusions ?? []).join(". "), faqs].join(" ")),
      headings: 2,
      facts: { metaTitle: s.metaTitle ?? null, metaDescription: s.metaDescription ?? null },
    };
  }
  throw new ToolError(`Unknown path "${clean}". Supported: /, /product/<id>, /blog/<id>, /service/<slug>.`);
};

type AuditStatus = "pass" | "warn" | "fail";
type AuditCheck = { check: string; status: AuditStatus; weight: number; detail: string }
const GAIN: Record<AuditStatus, number> = { pass: 1, warn: 0.5, fail: 0 };
const titleAngle = (t: string) => { const len = t.trim().length; return len >= 30 && len <= 60 ? "pass" : len >= 10 && len <= 70 ? "warn" : "fail"; };
const descAngle = (t: string) => { const len = t.trim().length; return len >= 120 && len <= 160 ? "pass" : len >= 70 && len < 200 ? "warn" : "fail"; };

export const seoAuditPage = defineTool({
  name: "seo_audit_page",
  title: "SEO audit (advisory)",
  description: "Advisory, read-only SEO audit of a WOODEX page (/, /product/<id>, /blog/<id>, /service/<slug>). Deterministic checks on title, meta description, focus keyphrase usage, body depth and slug hygiene. No external calls; never mutates anything.",
  inputSchema: {
    path: z.string().min(1).describe("Site path, e.g. '/product/ballmer-executive-desk' or '/blog/custom-office-furniture-cost'."),
    focusKeyphrase: z.string().min(1).optional().describe("Optional focus keyphrase to check (case-insensitive)."),
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ path, focusKeyphrase }: { path: string; focusKeyphrase?: string }) => {
    const page = resolvePage(path);
    const key = focusKeyphrase?.trim();
    const words = wordCount(page.body);
    const keyCount = key ? countKey(page.body, key) : 0;
    const checks: AuditCheck[] = [
      { check: "title-length", weight: 15, status: titleAngle(page.title), detail: `${page.title.trim().length} chars (ideal 30–60): "${page.title.trim()}"` },
      { check: "meta-description", weight: 15, status: descAngle(page.description), detail: `${page.description.trim().length} chars (ideal 120–160)${page.description.trim() ? "" : " — missing"}` },
      { check: "slug-hygiene", weight: 10, status: /^\/(?:[a-z0-9-]+\/?)*$/.test(page.path) && page.path.length <= 75 ? "pass" : "warn", detail: `${page.path} — lowercase kebab-case, ≤75 chars recommended` },
      { check: "content-depth", weight: 15, status: words >= 300 ? "pass" : words >= 150 ? "warn" : "fail", detail: `${words} words of body copy (ideal ≥300)` },
      { check: "headings", weight: 10, status: page.headings >= 1 ? "pass" : "fail", detail: `${page.headings} heading block(s) detected in the snapshot` },
    ];
    if (key) {
      checks.push(
        { check: "keyphrase-in-title", weight: 10, status: includesKey(page.title, key) ? "pass" : "fail", detail: `"${key}" ${includesKey(page.title, key) ? "present" : "NOT found"} in title` },
        { check: "keyphrase-in-description", weight: 10, status: includesKey(page.description, key) ? "pass" : "fail", detail: `"${key}" ${includesKey(page.description, key) ? "present" : "NOT found"} in meta description` },
        { check: "keyphrase-density", weight: 15, status: keyCount >= 2 && keyCount <= 5 ? "pass" : keyCount === 1 ? "warn" : keyCount === 0 ? "fail" : "warn", detail: `${keyCount} occurrence(s) (ideal 2–5, avoid stuffing)` },
      );
    } else {
      checks.push({ check: "focus-keyphrase", weight: 35, status: "warn", detail: "No focus keyphrase supplied — pass focusKeyphrase for keyphrase, density and front-loading analysis" });
    }
    const total = checks.reduce((sum, c) => sum + c.weight, 0);
    const gained = checks.reduce((sum, c) => sum + c.weight * GAIN[c.status], 0);
    const score = Math.round((gained / total) * 100);
    const suggestions = checks
      .filter((c) => c.status !== "pass" && c.check !== "focus-keyphrase")
      .map((c) => {
        switch (c.check) {
          case "title-length": return "Rewrite the title to 30–60 characters, front-loading the focus keyphrase — try seo_generate_meta for a draft.";
          case "meta-description": return "Write a 120–160 character meta description that includes the focus keyphrase and one concrete benefit (warranty, made-to-order, delivery).";
          case "slug-hygiene": return "Normalise the slug to lowercase kebab-case and keep it short; keep the keyphrase in the slug.";
          case "content-depth": return "Expand the page body toward 300+ words with useful specifics (materials, dimensions, warranty, delivery timelines).";
          case "headings": return "Add at least one structured sub-heading so the page outline is crawlable.";
          case "keyphrase-in-title": return "Move the focus keyphrase into the title, ideally within the first 60 characters.";
          case "keyphrase-in-description": return "Include the focus keyphrase verbatim in the meta description.";
          case "keyphrase-density": return "Use the focus keyphrase 2–5 times naturally across the body; more looks like stuffing.";
          default: return `Review ${c.check}: ${c.detail}`;
        }
      });
    suggestions.push(`Ensure a self-referencing canonical tag on ${SITE_ORIGIN}${page.path} and keep one canonical per URL.`);
    if (page.type === "product") suggestions.push("Keep Product JSON-LD (price, availability, aggregateRating) in the <head> — already wired sitewide for catalogue pages.");
    const result = {
      path: page.path, type: page.type, score,
      title: page.title.trim(), description: page.description.trim(),
      wordCount: words, focusKeyphrase: key ?? null,
      checks,
      suggestions,
      canonical: `${SITE_ORIGIN}${page.path}`,
      readOnly: true,
    };
    return { content: [{ type: "text", text: JSON.stringify(result) }], structuredContent: result };
  },
});

export const seoGenerateMeta = defineTool({
  name: "seo_generate_meta",
  title: "Generate SEO meta (advisory)",
  description: "Deterministic, advisory title/description suggestions for a WOODEX page. No external AI calls; templates keyed off the focus keyphrase with 60/160-character word-boundary trims. Read-only output for an editor to apply.",
  inputSchema: {
    title: z.string().min(3).describe("Current page title or working topic, e.g. 'Ballmer Executive Desk'."),
    focusKeyphrase: z.string().min(2).describe("Focus keyphrase, e.g. 'executive office desk Lahore'."),
    pageType: z.enum(["home", "product", "blog", "service", "category", "generic"]).optional().describe("Page family; tunes the benefit clause (default generic)."),
    brand: z.string().optional().describe("Brand suffix (default WOODEX)."),
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ title, focusKeyphrase, pageType, brand }: { title: string; focusKeyphrase: string; pageType?: "home" | "product" | "blog" | "service" | "category" | "generic"; brand?: string }) => {
    const brandName = (brand ?? "WOODEX").trim() || "WOODEX";
    const key = focusKeyphrase.trim();
    const kind = pageType ?? "generic";
    const benefit: Record<string, string> = {
      home: "honest PKR pricing, a 5-year warranty and nationwide delivery",
      product: "in-stock and made-to-order, backed by a 5-year warranty",
      blog: "expert, evidence-backed guidance from Lahore's furniture workshop",
      service: "end-to-end, engineered in our own Lahore workshop",
      category: "compare options with transparent PKR pricing",
      generic: "engineered in Lahore with a 5-year warranty",
    };
    const cta = kind === "blog" ? "Read the full guide." : "Book a showroom visit today.";
    const titleWithKey = includesKey(title, key) ? stripTags(title) : `${key.replace(/(^|\s)\S/g, (c: string) => c.toUpperCase())} — ${stripTags(title)}`;
    const suggestedTitle = trimWords(titleWithKey, 60);
    const described = `${stripTags(title)} — ${benefit[kind]}. ${cta}`;
    const withKey = includesKey(described, key) ? described : `${key} — ${described}`;
    const suggestedDescription = trimWords(withKey, 160);
    const ogTitle = trimWords(titleWithKey, 90);
    const ogDescription = trimWords(withKey, 200);
    const ogType = kind === "product" ? "product" : kind === "blog" ? "article" : "website";
    const keyIndex = norm(suggestedTitle).indexOf(norm(key));
    const analysis = {
      titleLength: suggestedTitle.length,
      descriptionLength: suggestedDescription.length,
      titleHasKeyphrase: includesKey(suggestedTitle, key),
      descriptionHasKeyphrase: includesKey(suggestedDescription, key),
      keyphraseFrontLoaded: keyIndex === 0,
      keyphraseIndexInTitle: keyIndex === -1 ? null : keyIndex,
      occurrencesInTitle: countKey(suggestedTitle, key),
      slug: kebab(key),
      slugHasKeyphrase: true,
      stuffingRisk: countKey(suggestedTitle, key) > 1 || countKey(suggestedDescription, key) > 2,
    };
    const warnings: string[] = [];
    if (!analysis.titleHasKeyphrase) warnings.push("Focus keyphrase did not fit the trimmed title — shorten the keyphrase or the base title.");
    if (!analysis.descriptionHasKeyphrase) warnings.push("Focus keyphrase was trimmed out of the description — front-load it in the keyphrase argument.");
    if (analysis.stuffingRisk) warnings.push("Keyphrase density drifts toward stuffing — keep one occurrence in title, one or two in description.");
    if (suggestedTitle.replace(/…$/, "").trim().length < 30) warnings.push("Suggested title is under 30 characters — fine for a category stub, thin for a money page.");
    const result = {
      input: { title: stripTags(title), focusKeyphrase: key, pageType: kind, brand: brandName },
      suggestions: {
        title: { value: suggestedTitle, length: suggestedTitle.length },
        metaDescription: { value: suggestedDescription, length: suggestedDescription.length },
        ogTitle: { value: ogTitle, length: ogTitle.length },
        ogDescription: { value: ogDescription, length: ogDescription.length },
        ogType,
        twitterCard: "summary_large_image",
        slug: analysis.slug,
        canonical: `${SITE_ORIGIN}/${analysis.slug}`,
      },
      focusKeyphraseAnalysis: analysis,
      warnings,
      note: "Advisory only — nothing is written back to any page. Apply in the editor (Admin → Pages / site pages) and re-run seo_audit_page to verify. For the admin builder's local Yoast-style Analyse, see the Wave 5 SEO layer (PB-5).",
      readOnly: true,
    };
    return { content: [{ type: "text", text: JSON.stringify(result) }], structuredContent: result };
  },
});
